<div class="heading"><div><h1>Webmail</h1><p>Read and send messages through your configured mail server.</p></div><a class="button secondary" href="/dashboard">Dashboard</a></div>
<?php if($error): ?><p class="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endif; ?>
<?php if(isset($_GET['sent'])): ?><p class="notice">Message accepted by the SMTP server.</p><?php endif; ?>
<?php if(isset($_GET['moved'])): ?><p class="notice">Message moved.</p><?php endif; ?>
<?php if(!$mailboxes): ?><section class="panel"><p>No active mailbox is assigned to your account.</p></section><?php else: ?>
<section class="panel">
<form method="get" action="/mail" class="toolbar"><label>Mailbox<select name="mailbox" onchange="this.form.submit()"><?php foreach($mailboxes as $m): ?><option value="<?= (int)$m['id'] ?>" <?= (int)($activeMailbox['id']??($_GET['mailbox']??0))===(int)$m['id']?'selected':'' ?>><?= htmlspecialchars($m['email'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><input type="hidden" name="folder" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"></form>
<?php if($activeMailbox): ?>
<div class="mail-layout">
<aside class="folder-list"><h2>Folders</h2><?php foreach($folders as $folder): ?><a class="<?= $folder['name']===$selectedFolder?'active':'' ?>" href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($folder['name']) ?>"><?= htmlspecialchars($folder['name'], ENT_QUOTES, 'UTF-8') ?></a><?php endforeach; ?></aside>
<section class="message-column"><h2><?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?></h2>
<?php if(!$messages): ?><p class="muted">This folder is empty.</p><?php else: ?><div class="message-list"><?php foreach($messages as $message): ?><a class="message-row <?= $message['seen']?'':'unread' ?>" href="/mail?mailbox=<?= (int)$activeMailbox['id'] ?>&folder=<?= rawurlencode($selectedFolder) ?>&uid=<?= (int)$message['uid'] ?>"><span><?= htmlspecialchars($message['from'], ENT_QUOTES, 'UTF-8') ?></span><strong><?= htmlspecialchars($message['subject'], ENT_QUOTES, 'UTF-8') ?></strong><time><?= htmlspecialchars($message['date'], ENT_QUOTES, 'UTF-8') ?></time></a><?php endforeach; ?></div><?php endif; ?>
<?php if($selectedMessage): ?><article class="panel message-detail"><h2><?= htmlspecialchars($selectedMessage['subject'], ENT_QUOTES, 'UTF-8') ?></h2><p><strong>From:</strong> <?= htmlspecialchars($selectedMessage['from'], ENT_QUOTES, 'UTF-8') ?></p><p><strong>To:</strong> <?= htmlspecialchars($selectedMessage['to'], ENT_QUOTES, 'UTF-8') ?></p><p><strong>Date:</strong> <?= htmlspecialchars($selectedMessage['date'], ENT_QUOTES, 'UTF-8') ?></p><pre><?= htmlspecialchars($selectedMessage['body'], ENT_QUOTES, 'UTF-8') ?></pre><form method="post" action="/mail/move" class="inline"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="uid" value="<?= (int)$selectedMessage['uid'] ?>"><input type="hidden" name="source" value="<?= htmlspecialchars($selectedFolder, ENT_QUOTES, 'UTF-8') ?>"><?php $trash = in_array('Trash', array_column($folders,'name'), true) ? 'Trash' : (in_array('Deleted Items', array_column($folders,'name'), true) ? 'Deleted Items' : ''); ?><?php if($trash): ?><input type="hidden" name="destination" value="<?= htmlspecialchars($trash, ENT_QUOTES, 'UTF-8') ?>"><button class="danger small">Move to Trash</button><?php endif; ?></form></article><?php endif; ?>
</section></div>
<?php else: ?><p class="muted">Select an active mailbox to continue.</p><?php endif; ?></section>
<?php if($activeMailbox): ?><section class="panel compose"><h2>Compose</h2><form method="post" action="/mail/send"><input type="hidden" name="_csrf" value="<?= htmlspecialchars(\App\Core\Csrf::token()) ?>"><input type="hidden" name="mailbox_id" value="<?= (int)$activeMailbox['id'] ?>"><input type="hidden" name="sent_folder" value="<?= htmlspecialchars(in_array('Sent',array_column($folders,'name'),true)?'Sent':'INBOX', ENT_QUOTES, 'UTF-8') ?>"><label>From<input readonly value="<?= htmlspecialchars($activeMailbox['email'], ENT_QUOTES, 'UTF-8') ?>"></label><label>To<input name="to" required placeholder="recipient@example.com (separate multiple recipients with commas)"></label><label>Subject<input name="subject" maxlength="998"></label><label>Message<textarea name="body" rows="8" required></textarea></label><button type="submit">Send message</button></form></section><?php endif; ?>
<?php endif; ?>
